void bubbleSort(int[] a) {
    for (int i = 0; i < a.length - 1; i++) {
        boolean swapped = false;
        for (int j = 0; j < a.length - 1 - i; j++) {   // last i are settled
            if (a[j] > a[j + 1]) {
                int t = a[j]; a[j] = a[j + 1]; a[j + 1] = t;
                swapped = true;
            }
        }
        if (!swapped) break;          // no swaps => already sorted => O(n)
    }
}

// {5,1,4,2}: pass1 -> {1,4,2,5}; pass2 -> {1,2,4,5}; pass3 no swap -> stop
```

```java
// Primitives -> dual-pivot quicksort (not stable, but doesn't matter)
int[] nums = {5, 3, 8, 1};
Arrays.sort(nums);                 // [1, 3, 5, 8]

// Objects -> TimSort (stable)
record Emp(String name, int dept) {}
Emp[] emps = { new Emp("Ann", 2), new Emp("Bo", 1), new Emp("Cy", 2) };
Arrays.sort(emps, Comparator.comparingInt(Emp::dept));
// dept order preserved AND Ann stays before Cy (both dept 2) -> stable

List<Emp> list = new ArrayList<>(List.of(emps));
list.sort(Comparator.comparingInt(Emp::dept));   // also TimSort
```

