void mergeSort(int[] a, int lo, int hi) {
    if (lo >= hi) return;                 // base: 0 or 1 element
    int mid = lo + (hi - lo) / 2;
    mergeSort(a, lo, mid);                // sort left
    mergeSort(a, mid + 1, hi);            // sort right
    merge(a, lo, mid, hi);                // combine
}
void merge(int[] a, int lo, int mid, int hi) {
    int[] tmp = new int[hi - lo + 1];     // O(n) buffer
    int i = lo, j = mid + 1, k = 0;
    while (i <= mid && j <= hi)
        tmp[k++] = (a[i] <= a[j]) ? a[i++] : a[j++];  // <= keeps it stable
    while (i <= mid) tmp[k++] = a[i++];
    while (j <= hi)  tmp[k++] = a[j++];
    System.arraycopy(tmp, 0, a, lo, tmp.length);
}

// {5,2,4,1}: split->{5,2}{4,1}->sort->{2,5}{1,4}->merge->{1,2,4,5}
